const chapters = [
    { id: 0, title: "Prologue", filename: "ch1_On rêve + Prologue.md", season: 1, tapasLink: "https://tapas.io/episode/3635296", preview: "On a toujours rêvé, moi et Max, d'échapper à ce monde gris qu'était la\nTerre, les rêves ont longtemps été un refuge... jusqu'à ce qu'on décide\nde les transformer en terrain de jeu. Grâce au rêve lucide, chose qu'on\na réussi à maîtriser à l'aide d'une technologie qu'on a bricolée avec\nMax -- une sorte de mode multijoueur mais pour les rêves. Après quelques\nmois à s'amuser dedans, à passer nos nuits dedans, on a décidé de créer\nquelque chose de plus concret. Un monde entier. De A à Z.\n\nL'idée était que chaque nuit, dès qu'on s'endort, on vit une vie\nparallèle à la nôtre. Ce monde, c'est Parralela. Notre monde. Tout ce\nqu'on aime s'y trouve. De la magie, évidemment. Pas juste des sorts\nbasiques jetés au hasard qui apparaissent comme ça, non... Un vrai\nsystème développé, lié à une vraie logique et qui suit les lois de la\nphysique. Bon, d'accord, j'ai surtout bossé là-dessus tout seul -- Max\ns'est contenté de valider.\n\nEn gros, Parralela, une planète présente dans un système planétaire.\nHuit planètes, sans compter Parralela, chacune liée à un élément : Pyros\npour le feu, Aquaria pour l'eau, Umbra pour l'ombre, etc. Mais ça ne\ns'arrête pas là : chaque planète a trois satellites naturels (des\nlunes), qui précisent et complexifient la magie. Par exemple, Fulgora\n(l'électricité) combinée avec Tempestra (un satellite) permet de\ncanaliser des décharges électriques pures, plus puissantes. Alors que si\non prend Electra, qui est également un satellite de Fulgora, elle permet\nun magnétisme et une manipulation des métaux. Au début ça paraît\ncompliqué, mais en réalité... ça marche tout seul.\n\nEnfin bref, inutile de rentrer dans les détails ici. Ce n'est pas un\nmanuel de magie.\n\nLa seule chose qu'il faut savoir, c'est qu'on a bâti un monde sans\nhistoire écrite. On voulait que tout naisse naturellement, que les\nhabitants de Parralela inventent leur propre récit. Ouais, on a même\nlaissé le hasard gérer la création des créatures et des peuples. Plus\nimprévisible, plus vivant, rien de mieux !\n\nQuant à moi, je me nomme Allan -- mais plus pour longtemps." },
    { id: 1, title: "Prologue", filename: "ch1_On rêve + Prologue.md", season: 1, tapasLink: "https://tapas.io/episode/3635298", preview: "Max et Allan touchent au but. Leur monde onirique, Parralela, est presque achevé. Mais ce qui n'était qu'un jeu de création lucide s'apprête à devenir bien plus réel qu'ils ne l'avaient imaginé." },
    { id: 2, title: "Nouveau départ", filename: "ch2_ Nouveau départ.md", season: 1, tapasLink: "https://tapas.io/episode/3635300", preview: "Le néant a laissé place à une lumière aveuglante. Allan s'éveille dans un corps qui n'est pas le sien, au cœur d'un monde qu'il pensait connaître par cœur. Mais Parralela a ses propres règles, et le réveil est brutal." },
    { id: 3, title: "Le Troisième Élément", filename: "ch3_Le Troisième Element.md", season: 1, tapasLink: "https://tapas.io/episode/3635301", preview: "Neuf mois se sont écoulés depuis l'arrivée. Réapprendre à marcher, à parler, à vivre dans ce nouveau corps est un défi quotidien. Mais Allan devenu Lily n'est pas seul : une nouvelle famille l'entoure, et les premiers signes de magie se manifestent." },
    { id: 4, title: "Finn Ashford", filename: "ch4_Finn Ashford.md", season: 1, tapasLink: "https://tapas.io/episode/3635303", preview: "Quatre années se sont écoulées sur Parralela. Le temps y est différent, plus lent, plus dense. Lily et Nova grandissent, s'adaptent, et découvrent que leur création leur réserve encore bien des surprises." },
    { id: 5, title: "La vraie gestion du mana", filename: "ch5_La vraie gestion du mana.md", season: 1, tapasLink: "https://tapas.io/episode/3635304", preview: "Le duo devient trio. Finn Ashford, une boule d'énergie explosive, rejoint Lily et Nova. Entre entraînements clandestins et maîtrise du mana, les trois enfants commencent à tisser des liens qui forgeront leur destin." },
    { id: 6, title: "Vers les Hauteurs", filename: "ch6_ Vers les hauteurs.md", season: 1, tapasLink: "https://tapas.io/episode/3635306", preview: "La clairière ne suffit plus. Leurs pouvoirs grandissants exigent un nouveau terrain de jeu, loin des regards. L'appel des hauteurs se fait sentir, là où la magie peut s'exprimer sans retenue." },
    { id: 7, title: "Le repère", filename: "ch7_Le repère.md", season: 1, tapasLink: "https://tapas.io/episode/3635308", preview: "Une ruine oubliée, perchée sur la montagne. Ce lieu silencieux et bancal semble les attendre. Ce ne sera pas seulement un terrain d'entraînement, mais leur premier véritable quartier général." },
    { id: 8, title: "Le fragment", filename: "ch8_Le fragment.md", season: 1, tapasLink: "https://tapas.io/episode/3635310", preview: "Une soirée paisible bascule en un instant. Alors que l'Étoile se couche sur la vallée, un événement céleste vient bouleverser l'équilibre. Un fragment de Parralith Pure traverse le ciel, et sa destination n'est pas le hasard." },
    { id: 9, title: "Plus loin dans la montagne", filename: "ch9_Plus loin dans la montagne.md", season: 1, tapasLink: "https://tapas.io/episode/3635312", preview: "Deux ans après l'impact, le fragment est toujours là, logé dans la poitrine de Lily. Loin d'être un fardeau, il est devenu une source de puissance et de mystère. L'entraînement s'intensifie, car le monde ne restera pas paisible éternellement." },
    { id: 10, title: "Premier donjon", filename: "ch10_Premier donjon.md", season: 1, tapasLink: "https://tapas.io/episode/3635349", preview: "Une fissure dans la roche, un souffle froid qui s'en échappe. Ce n'est pas une simple grotte, mais un donjon. Le premier véritable test pour le trio, là où la théorie laisse place à la réalité du danger." },
    { id: 11, title: "Les tensions", filename: "ch11_Les Tensions.md", season: 1, tapasLink: "https://tapas.io/episode/3638218", preview: "La saison d'Umbralis pèse sur les esprits. La boue, le froid et la fatigue mettent les nerfs à vif. La recherche de nouveaux défis crée des frictions au sein du groupe, mais le danger a le don de ressouder les liens." },
    { id: 12, title: "Trois Duels", filename: "ch12_Trois duels.md", season: 1, tapasLink: "https://tapas.io/episode/3642359", preview: "C'est le jour du jugement. Les duels ne sont pas qu'un simple entraînement, c'est une mesure de leur progression. L'air est électrique, et chacun sait que l'issue de ces combats définira la hiérarchie de leur force." },
    { id: 13, title: "Frisson Rouge", filename: "ch13_Frisson Rouge.md", season: 1, tapasLink: "https://tapas.io/episode/3645432", preview: "L'arène a révélé une facette sombre de la magie. Une lumière rouge, une sensation de brûlure, et ce sang qui n'est pas le sien. Lily découvre que ses pouvoirs pourraient bien avoir un coût qu'elle n'avait pas anticipé." },
    { id: 14, title: "Sous la peau de la montagne", filename: "ch14_Sous la peau de la montagne.md", season: 1, tapasLink: "https://tapas.io/episode/3648746", preview: "La chaleur de Flarealis écrase la vallée. Sous l'Étoile implacable, la montagne semble vivante. Le trio reprend l'ascension vers le Perchoir, mais cette fois, la chaleur n'est pas la seule chose qui les guette." },
    { id: 15, title: "Affinité Jumelle", filename: "ch15_Affinité Jumelle.md", season: 1, tapasLink: "https://tapas.io/episode/3652028", preview: "Dans les ténèbres d'un donjon, la lumière est un luxe. Nova se retrouve confronté à ses propres peurs, privé de repères. Mais c'est dans l'obscurité que les affinités se révèlent parfois les plus puissantes." },
    { id: 16, title: "L'anniversaire", filename: "ch16_L'Anniversaire.md", season: 1, tapasLink: "https://tapas.io/episode/3657902", preview: "Une pause dans la tempête. Aujourd'hui, pas de magie, pas de combat, juste un moment de répit pour célébrer. Mais même au cœur de la fête, l'ombre de leur destin n'est jamais bien loin." },
    { id: 17, title: "Le lendemain des cadeaux", filename: "ch17_Le lendemain des cadeaux.md", season: 1, tapasLink: "https://tapas.io/episode/3661484", preview: "La fête est finie, les armes sont sorties. La dague et le chakram ne sont pas des jouets, mais des promesses d'avenir. Le temps de l'innocence s'effrite un peu plus à chaque aube." },
    { id: 18, title: "Le rugissement", filename: "ch18_Le rugissement.md", season: 1, tapasLink: "https://tapas.io/episode/3662327", preview: "Un bruit sourd, puis le silence absolu. La nature elle-même semble retenir son souffle. Quand Galen sort armé, le trio comprend que l'entraînement est terminé. La vraie menace est là." },
    { id: 19, title: "Le fil qui recommence", filename: "ch19_Le fil qui recommence.md", season: 1, tapasLink: "https://tapas.io/episode/3665788", preview: "Le choc passé, la vie reprend ses droits, mais rien n'est plus tout à fait comme avant. Les blessures guérissent, les rires reviennent, mais une nouvelle vigilance s'est installée dans la maison Eloiranôr." },
    { id: 20, title: "Moteur de neige", filename: "ch20_Moteur de neige.md", season: 1, tapasLink: "https://tapas.io/episode/3669833", preview: "L'hiver n'arrête pas l'ingéniosité. Autour d'un établi massif, sous la neige, un nouveau projet prend forme. Ce ne sera pas une arme, mais quelque chose de plus grand, de plus complexe." },
    { id: 21, title: "Premier façonnage", filename: "ch21_Premier façonnage.md", season: 1, tapasLink: "https://tapas.io/episode/3673947", preview: "Le marché de Tharis grouille de vie et de froid. Au milieu de la foule, le trio cherche sa place et ses ressources. C'est ici, entre deux étals, que se jouent parfois les rencontres les plus décisives." },
    { id: 22, title: "Révélation à la guilde", filename: "ch22_Révélation à la guilde.md", season: 1, tapasLink: "https://tapas.io/episode/3678190", preview: "Un an de bricolage, d'échecs et de petites victoires. Les gadgets s'accumulent, mais l'ambition grandit. Le prochain objectif est colossal : un réservoir de mana. Mais pour ça, il faut des fonds, et la Guilde est la clé." },
    { id: 23, title: "L'ombre d'une piste", filename: "ch23_L'ombre d'une piste.md", season: 1, tapasLink: "https://tapas.io/episode/3681241", preview: "Ils sont officiellement aventuriers, rang Lune Mineure. Un titre modeste pour de grandes ambitions. En quittant la Guilde, ils emportent avec eux plus qu'une simple carte : une piste vers leur prochain grand défi." },
    { id: 24, title: "La pierre qui respire", filename: "ch24_La Pierre qui respire.md", season: 1, tapasLink: "https://tapas.io/episode/3689452", preview: "La parralith est à portée de main, mais elle ne se laissera pas prendre facilement. Une expédition nocturne se prépare, clandestine et risquée. Il faudra ruser, non seulement avec le terrain, mais aussi avec l'autorité parentale." },
    { id: 25, title: "Le poids des ailes", filename: "ch25_Le poids des ailes.md", season: 1, tapasLink: "https://tapas.io/episode/3690523", preview: "Le réveil est difficile. Les corps sont lourds, marqués par l'effort de la veille. Mais la fatigue est le prix de l'expérience. Chaque courbature raconte une histoire de dépassement de soi." },
    { id: 26, title: "Respire en ailes", filename: "ch26_Respire en ailes.md", season: 1, tapasLink: "https://tapas.io/episode/3693385", preview: "Sur le Perchoir, face au vide, Lily cherche l'équilibre. Au-delà de la force brute, il y a la maîtrise, le souffle, l'inspiration. Et dans le ciel, l'image d'une buse lui souffle une idée qui pourrait tout changer." },
    { id: 27, title: "Buse et Sang", filename: "ch27_Buse et Sang.md", season: 1, tapasLink: "https://tapas.io/episode/3698769", preview: "C'est l'heure du test grandeur nature. Seul, face aux éléments, Lily s'apprête à repousser ses limites. Mais l'audace a un prix, et la ligne entre le succès et la catastrophe est parfois aussi fine qu'une lame." },
    { id: 28, title: "Vers Fertol !", filename: "ch28_Vers Fertol !.md", season: 1, tapasLink: "https://tapas.io/episode/3702486", preview: "La fin de l'année approche, et avec elle, la promesse de la grande fête de Fertol. Le voyage s'annonce comme une parenthèse enchantée, loin des soucis quotidiens. Une aventure d'un autre genre commence." },
    { id: 29, title: "Pages de Buse", filename: "ch29_Pages de Buse.md", season: 1, tapasLink: "https://tapas.io/episode/3709063", preview: "Fertol ne dort jamais. La ville est un tourbillon de bruits, d'odeurs et de couleurs qui ferait passer Tharis pour un village endormi. Dans ce chaos organisé, le trio découvre un nouveau terrain de jeu urbain." },
    { id: 30, title: "La foudre et la foule", filename: "ch30_La foudre et la foule.md", season: 1, tapasLink: "https://tapas.io/episode/3709067", preview: "Le festival bat son plein. La foule est une marée vivante, la musique résonne à chaque coin de rue. Au cœur de cette effervescence, la magie n'est pas que dans les sorts, elle est dans l'air, électrique et contagieuse." },
    { id: 31, title: "Nulléon -- Le silence du monde", filename: "ch31_Nulléon - Le silence du monde.md", season: 1, tapasLink: "https://tapas.io/episode/3714910", preview: "Le retour au calme est brutal mais nécessaire. Loin du tumulte de Fertol, Lily se consacre à une nouvelle création : Nulléon. Un projet silencieux qui pourrait bien faire plus de bruit qu'une explosion de Finn." },
    { id: 32, title: "Les Drakyns", filename: "ch32_Les Drakyns.md", season: 1, tapasLink: "https://tapas.io/episode/3719284", preview: "Nulléon est né, mais il faut maintenant le maîtriser. L'ennui guette à la Guilde, et l'envie d'action se fait pressante. Une mission de routine pourrait bien se transformer en quelque chose de beaucoup plus intéressant." },
    { id: 33, title: "L'Hurlement du Vide", filename: "ch33_L'Hurlement du Vide.md", season: 1, tapasLink: "https://tapas.io/episode/3721598", preview: "Les ruines ne sont jamais vraiment vides. Des ombres s'agitent, des yeux s'allument. Les Drakyns sont là, et ils ne sont pas venus pour discuter. Le combat s'engage, et cette fois, c'est pour de vrai." },
    { id: 34, title: "L'Étincelle Forgée", filename: "ch34_L'Étincelle Forgée.md", season: 1, tapasLink: "https://tapas.io/episode/3721610", preview: "Un an s'est écoulé. Les saisons ont tourné, les corps ont grandi, mais les ambitions sont restées les mêmes. Cette année n'était pas une pause, c'était une inspiration." },
    { id: 35, title: "L'Héritage en Mouvement", filename: "ch35_L'Héritage en Mouvement.md", season: 1, tapasLink: "https://tapas.io/episode/3754079", preview: "Les plans sont tracés, les matériaux listés. Mais la théorie se heurte vite à la réalité des ressources. Pour forger des armes légendaires, il faut plus que de l'or : il faut des guides." },
    { id: 36, title: "Les Pas des Anciens", filename: "ch36_Les Pas des Anciens.md", season: 1, tapasLink: "https://tapas.io/episode/3758921", preview: "Ils sont arrivés. Des silhouettes familières pour les parents, mais des légendes pour les enfants. L'histoire de la vieille équipe se dévoile, et avec elle, le poids du passé." },
    { id: 37, title: "Le Premier pas", filename: "ch37_Le Premier pas.md", season: 1, tapasLink: "https://tapas.io/episode/3758929", preview: "Le seuil est franchi. Tharis s'éloigne, et devant eux s'étend l'inconnu. Ce n'est plus une simple sortie, c'est le début d'un voyage qui les changera à jamais." },
    { id: 38, title: "Sous le Monde", filename: "ch38_Sous le Monde.md", season: 1, tapasLink: "https://tapas.io/episode/3761313", preview: "Loin du ciel ouvert, la terre se referme. Les tunnels de Varnhalt ne sont pas juste sombres, ils sont vivants. Et pour passer, il faudra payer le prix de la sueur." },
    { id: 39, title: "Premier matériau", filename: "ch39_Premier matériau.md", season: 1, tapasLink: "https://tapas.io/episode/3763423", preview: "Dans la lueur des champignons géants, le danger a une autre forme. L'Ombre-Écaille n'est pas un minérai, c'est une part de ténèbres. Et pour l'obtenir, Nova devra plonger dans son propre élément." },
    { id: 40, title: "Karthrun", filename: "ch40_Karthrun.md", season: 1, tapasLink: "https://tapas.io/episode/3770207", preview: "Une cité sous la roche, éclairée par des cristaux millénaires. Karthrun n'est pas une simple étape, c'est une civilisation à part entière. Ici, la magie a une autre saveur, plus brute, plus ancienne." },
    { id: 41, title: "Les Couloirs vers le Nord\\", filename: "ch41_Les Couloirs vers le Nord.md", season: 1, tapasLink: "https://tapas.io/episode/3772509", preview: "Le chemin remonte, mais l'épreuve n'est pas finie. Entre les racines de pierre et les échos lointains, le groupe avance vers le froid. Chaque pas les rapproche de la surface, et d'un nouveau défi." },
    { id: 42, title: "Le Cristal Binaire", filename: "ch42_Le Cristal Binaire.md", season: 1, tapasLink: "https://tapas.io/episode/3776999", preview: "Un miroir naturel, une énigme de lumière. Le Cristal Binaire ne se contente pas de refléter l'image, il dédouble la réalité. Lily devra voir au-delà des apparences pour saisir ce qui est vrai." },
    { id: 43, title: "Quattro ?", filename: "ch43_Quattro.md", season: 1, tapasLink: "https://tapas.io/episode/3777002", preview: "Garn-Khuzar, la cité de fer et de feu. Dans ce dédale industriel, une rencontre inattendue va bouleverser l'équilibre du groupe. Ils étaient trois, ils pourraient bien repartir quatre." },
    { id: 44, title: "La fille", filename: "ch44_La fille.md", season: 1, tapasLink: "https://tapas.io/episode/3783279", preview: "Un matin étrange, des regards en coin. L'arrivée de la nouvelle venue ne passe pas inaperçue. Entre méfiance et curiosité, le groupe tente de comprendre qui elle est vraiment." },
    { id: 45, title: "Cendres d'une chasse", filename: "ch45_Cendres d'une chasse.md", season: 1, tapasLink: "https://tapas.io/episode/3786212", preview: "La traque commence. Séparés pour mieux chercher, ils découvrent que la proie n'est pas la seule à être dangereuse. Les cendres du passé se mêlent à la poussière du présent." },
    { id: 46, title: "Repos des Cendres", filename: "ch46_Repos des Cendres.md", season: 1, tapasLink: "https://tapas.io/episode/3786217", preview: "Le retour au camp est amer. Les blessures ne sont pas que physiques. Autour du feu, les silences en disent long sur les épreuves traversées. Mais c'est aussi là que se forgent les liens les plus solides." },
    { id: 47, title: "Kérugan", filename: "ch47_Kérugan.md", season: 1, tapasLink: "https://tapas.io/episode/3791620", preview: "La bête est là, tapie dans les ombres industrielles. Le Kérugan n'est pas une simple créature, c'est une force de la nature. Pour le vaincre, il faudra plus que de la force : il faudra une coordination parfaite." },
    { id: 48, title: "Retour à la surface", filename: "ch48_Retour à la surface.md", season: 1, tapasLink: "https://tapas.io/episode/3791623", preview: "L'air libre, enfin. Après les profondeurs étouffantes, le ciel immense est une libération. Mais la lumière du soleil révèle aussi les cicatrices laissées par l'obscurité." },
    { id: 49, title: "L'Art du Silence et du Fracas", filename: "ch49_L'Art du Silence et du Fracas.md", season: 1, tapasLink: "https://tapas.io/episode/3798104", preview: "Hochedenia, l'académie de magie. Un lieu de savoir, mais aussi de secrets. Lily et Nova découvrent que le silence peut être aussi puissant que le fracas, et que la magie a ses propres codes." },
    { id: 50, title: "Les Fantômes d'Hochedenia", filename: "ch50_Les Fantômes d'Hochedenia.md", season: 1, tapasLink: "https://tapas.io/episode/3802651", preview: "Les murs ont des oreilles, et les couloirs ont une mémoire. En fouillant dans les archives interdites, ils réveillent des fantômes qu'il aurait peut-être mieux valu laisser dormir." },
    { id: 51, title: "Le Sillage des Hauteurs", filename: "ch51_Le Sillage Des Hauteurs.md", season: 1, tapasLink: "https://tapas.io/episode/3806914", preview: "La mer s'étend à perte de vue. Sur le navire qui les emmène vers Harmouth, l'horizon est une promesse. Mais les eaux calmes peuvent cacher des tempêtes intérieures." },
    { id: 52, title: "L'Ombre des Racines", filename: "ch52_L’Ombre des Racines.md", season: 1, tapasLink: "https://tapas.io/episode/3811105", preview: "Harmouth, la cité dans les arbres. Ici, on ne marche pas, on grimpe. Et pour Lily, apprendre à voler n'est pas une option, c'est une nécessité vitale." },
    { id: 53, title: "La mécanique des ailes", filename: "ch53_La mécanique des ailes.md", season: 1, tapasLink: "https://tapas.io/episode/3811107", preview: "Ce n'est pas de la magie, c'est de la physique. Comprendre l'air, jouer avec les courants. Lily touche du doigt son rêve, mais la chute n'est jamais loin pour ceux qui visent le soleil." },
    { id: 54, title: "L'Abîme Liquide", filename: "ch54_L'Abîme Liquide.md", season: 1, tapasLink: "https://tapas.io/episode/3811110", preview: "Le vent me gifle dès qu'on touche la roche.\n\nPas un souffle gentil. Un vent qui mord, qui siffle entre les dents, qui te fait plisser les yeux même quand tu veux juste regarder devant toi. L'île flottante est minuscule, nue, comme une dent cassée arrachée au ciel. Pas de végétation, pas d'abri. Juste une peau de pierre sombre, striée de fissures, et le vide tout autour." },
    { id: 55, title: "L'Impulsion Céleste", filename: "ch55_L'Impulsion Céleste.md", season: 1, tapasLink: "https://tapas.io/episode/3811113", preview: "Je retrouve Cayden sur une piste de lancement taillée dans la roche claire d'Aérostel, un truc long et plat qui finit net... sur le vide -- un truc prévu pour les gros Aeloryn de base. Évidemment.\n\nLe vent accroche mes cheveux encore humides de la brume du matin, et mes muscles dorsaux me rappellent, comme une petite note passive-agressive, qu'ils sont toujours en « récupération ». Je roule les épaules, juste pour voir jusqu'où ça tire." },
    { id: 56, title: "L'Horizon Salé", filename: "ch56_L'Horizon Salé.md", season: 1, tapasLink: "https://tapas.io/episode/3811117", preview: "La dernière station d'Aérostel s'éloigne derrière nous comme une idée un peu trop légère pour être vraie.\n\nJe sens la gravité revenir par paliers, d'abord timidement, puis franchement, comme une main ferme qui me rappelle que mon corps est fait pour autre chose que jouer au caillou qui flotte. Et... en soi, c'est agréable. Mes bottes s'écrasent mieux. Mes hanches arrêtent de se prendre pour des ressorts capricieux. Mes cuisses, elles, me font payer chaque réception du Dash-Vol des derniers jours, mais c'est une..." },
    { id: 57, title: "Eaux Vivantes", filename: "ch57_Eaux Vivantes.md", season: 1, tapasLink: "https://tapas.io/episode/3822488", preview: "Je sens l'odeur avant même de voir les premières maisons.\n\nLe sel me prend à la gorge, pas méchamment, plutôt comme une claque familière. Une claque humide. Ça se mêle au souffle tiède de l'océan et à un truc... électrique. Comme si l'air lui-même frémissait." },
    { id: 58, title: "Pyrocrabes", filename: "ch58_Pyrocrabes.md", season: 1, tapasLink: "https://tapas.io/episode/3822557", preview: "Le port de Naris a cette façon étrange de te donner l'impression que tout est normal... alors que l'eau, juste là, te regarde comme un animal. Une étendue trop calme, trop lourde. L'« Eau Vivante », comme ils disent. Elle est magnifique, ouais. Mais surtout, elle a une volonté.\n\nJe m'étire discrètement, histoire de ne pas couiner devant tout le monde, et mes muscles me répondent immédiatement par un petit rappel très clair : - Hé, Lily, on a nagé dans du béton liquide hier, tu te souviens ?" },
    { id: 59, title: "Entre deux Eaux", filename: "ch59_Entre deux Eaux.md", season: 1, tapasLink: "https://tapas.io/episode/3822560", preview: "Finn fait un bruit tout à fait particulier quand il se fait attraper par la peau du col.\n\nUn mélange de protestation, de surprise et de -merde- avalé à moitié." },
    { id: 60, title: "Le Sillage des Saisons", filename: "ch60_Le Sillage des Saisons.md", season: 1, tapasLink: "https://tapas.io/episode/3822564", preview: "Le sel me colle encore à la peau.\n\nL'air d'Afordia - enfin de ses côtes - a ce truc... franchement, il te décape la tête. Ça sent les algues, la pierre humide, et cette odeur de vent qui te donne l'impression que tout est possible tant que tu restes sur la côte." },
    { id: 61, title: "L'Échiquier Sauvage", filename: "ch61_L’Échiquier Sauvage.md", season: 1, tapasLink: "https://tapas.io/episode/3822567", preview: "Je passe la lisière du Territoire Sauvage avec une sensation bizarre dans la poitrine --- pas de peur, pas vraiment. Plutôt ce mélange d'excitation et de prudence qui te colle au palais quand tu sais que tu vas enfin sortir des chemins que tout le monde connaît.\n\nLe relais de guilde disparaît vite derrière nous. Une ligne de constructions trop propres, trop droites, trop... civilisées. Devant, la forêt prend la place sans demander la permission. Des troncs hauts, des feuillages denses, une odeur de résine et de..." },
    { id: 62, title: "Deux jours de marche", filename: "ch62_Deux jours de marche.md", season: 1, tapasLink: "https://tapas.io/episode/3834707", preview: "Le Territoire Sauvage, c'est... autre chose.\n\nJe le sens dès les premières minutes. Pas de route. Pas de borne. Pas de règles non écrites collées aux murs d'une ville. Juste de la verdure à perte de vue, des troncs énormes, des lianes qui pendent comme des cordes, et cette odeur de terre humide qui te colle aux narines." },
    { id: 63, title: "L'Architecte et le Kirin", filename: "ch63_L’Architecte et le Kirin.md", season: 1, tapasLink: "https://tapas.io/episode/3834709", preview: "L'après-midi a cette lumière un peu trop propre qui donne l'impression que tout va bien. L'étoile tape sans être méchante, juste assez pour te faire croire que le monde est simple, que tu as juste à marcher dans la bonne direction et que, hop, tout s'aligne.\n\nSauf que non." },
    { id: 64, title: "Le Rire des Sabots", filename: "ch64_Le Rire des Sabots.md", season: 1, tapasLink: "https://tapas.io/episode/3834715", preview: "La fin de journée a cette couleur un peu sale qui colle à la peau.\n\nLa forêt du Territoire Sauvage ne se contente pas de devenir plus sombre, elle devient plus épaisse. Comme si l'air décidait, lui aussi, de se mettre en travers de la gorge. L'étoile descend lentement derrière les cimes, et les ombres prennent des angles nouveaux, plus pointus, plus... méchants." },
    { id: 65, title: "Désolé, Monde", filename: "ch65_Désolé, Monde.md", season: 1, tapasLink: "https://tapas.io/episode/3834717", preview: "DARRUN !\n\nLe cri de Hendor me traverse comme une lame, sec et viscéral, et pendant une fraction de battement - je sais même pas si je respire encore - tout se coupe." },
    { id: 66, title: "Le poids des révélations", filename: "ch66_Le poids des revelations.md", season: 1, tapasLink: "https://tapas.io/episode/3853843", preview: "Le vent a cette façon dégueulasse de te gifler quand t'as déjà plus de peau à offrir.\n\nJe marche, puis je ne marche plus, puis je marche encore. Mon corps obéit sans que j'aie besoin de lui parler. C'est un truc automatique, presque insultant : mes jambes savent faire, même quand ma tête est en miettes." },
    { id: 67, title: "Oh la fête !", filename: "ch67_Oh la fête!.md", season: 1, tapasLink: "https://tapas.io/episode/3855356", preview: "Oh la fête !\n\nLa forêt n'est plus." },
    { id: 68, title: "Le Quattro fait du tourisme", filename: "ch68_Le Quattro fait du tourisme.md", season: 1, tapasLink: "https://tapas.io/episode/3855359", preview: "Le bois de la rambarde est tiède sous ma paume, et ça me fait presque bizarre de pouvoir m'appuyer sans que ça tremble sous une secousse, un rugissement, ou un \"attention, ça va tomber\" à la seconde suivante.\n\nKeralis sent la soupe épicée, la pierre mouillée et le linge propre. Rien que ça, franchement, j'ai envie de rire. On sort à peine du Territoire Sauvage, et là, je suis en train d'écouter une aubergiste engueuler un gamin parce qu'il a couru dans la salle commune avec des bottes pleines de boue." },
    { id: 69, title: "Ombres et Chopes de « Pière »", filename: "ch69_Ombres et Chopes de Pière.md", season: 1, tapasLink: "https://tapas.io/episode/3855362", preview: "Le dernier bruit de Keralis se fait aspirer derrière nous comme si quelqu'un referme une porte trop lourde.\n\nJe ne sais même pas comment décrire le contraste autrement : là-haut, c'était encore de la pierre vivante, du commerce, des cris, des marteaux, des gens qui existent. Là, sur la route qui nous avale vers Karostos, j'ai l'impression qu'on marche dans une respiration plus lente. Une respiration qui ne nous appartient pas." },
    { id: 70, title: "Le Prix du Vide", filename: "ch70_Le Prix du Vide.md", season: 1, tapasLink: "https://tapas.io/episode/3868600", preview: "Karostos a deux visages.\n\nCelui qu'on nous montre d'abord, avec ses arches taillées dans la roche, ses plateformes suspendues, ses lampes accrochées aux parois comme des grappes d'étoiles tombées trop bas, ses odeurs de bière forte et de poussière humide. Et puis l'autre. Celui qui commence quand on descend encore, quand les rires deviennent plus courts, plus secs, et que les regards s'attardent une demi-seconde de trop sur les bourses, les armes, les mains." },
    { id: 71, title: "Vers les hauteurs silencieuses", filename: "ch71_Vers les hauteurs silencieuses.md", season: 1, tapasLink: "https://tapas.io/episode/3868603", preview: "L'air dehors me frappe comme une claque.\n\nAprès Karostos, tout paraît trop vaste. Le ciel, la lumière, le vent, même l'odeur de pierre chaude et d'herbe écrasée. J'ai l'impression qu'on sort du ventre d'une bête malade pour retomber dans un monde qui, lui, continue de respirer sans nous attendre. En soi, ça devrait me soulager tout de suite. Mais il y a encore quelque chose de collé à nous. Quelque chose de sale." },
    { id: 72, title: "L'Éclair et le Miroir", filename: "ch72_L'Éclair et le Miroir.md", season: 1, tapasLink: "https://tapas.io/episode/3868610", preview: "Le vent change dès qu'on quitte Luminaër.\n\nJe le sens tout de suite à la manière dont l'air cesse d'être un simple courant pour devenir une matière nerveuse, presque mauvaise, qui cogne contre les joues et siffle dans les reliefs de l'armure. Derrière nous, la ville de lumière s'éloigne en nappes blanches suspendues au-dessus du vide. Devant, il n'y a plus que les courants extérieurs, vastes, sombres, vivants d'une agitation qui ne ressemble à rien d'aimable." },
    { id: 73, title: "Nerf de Liane-Flamme", filename: "ch73_Nerf de Liane-Flamme.md", season: 1, tapasLink: "https://tapas.io/episode/3871088", preview: "Je comprends très vite qu'on ne sortira pas de Luminaër par les beaux chemins polis pour les pèlerins.\n\nHendor ne prend même pas la peine de nous regarder quand il bifurque vers une corniche humide, loin des circuits officiels. La pierre claire de la cité s'arrête net, comme si quelqu'un avait tranché le monde en deux. À partir de là, il n'y a plus qu'une faille maigre ouverte dans la falaise, un truc tellement étroit que je me demande franchement si on n'est pas en train de se faire avaler par la montagne." },
    { id: 74, title: "Gueule de bois et Cristal de Feu", filename: "ch74_Gueule de bois et Cristal de Feu.md", season: 1, tapasLink: "https://tapas.io/episode/3871091", preview: "La salle entière vibre comme si Valzira avait décidé de cogner sur les murs pour vérifier qu'ils tiennent encore debout avant le passage à la nouvelle année.\n\nFranchement, ça me va très bien." },
    { id: 75, title: "L'Arène et L'Écume", filename: "ch75_L'Arène et l'Écume.md", season: 1, tapasLink: "https://tapas.io/episode/3871096", preview: "Je me réveille avec cette sensation bizarre qu'il s'est passé trop de choses hier pour que le monde ait le droit d'être aussi calme ce matin.\n\nLa chambre est froide, l'air sec, et Valzira a déjà cette lumière pâle d'Aetheris qui donne l'impression que l'étoile réfléchit au lieu de briller. Pendant deux secondes, je reste immobile sous la couverture, à écouter les bruits étouffés de l'auberge. Des pas lourds dans le couloir. Un juron étouffé au rez-de-chaussée. Un meuble qu'on heurte. Quelqu'un qui gémit comme..." },
    { id: 76, title: "Le Souffle de l'Est", filename: "ch76_Le Souffle de l'Est.md", season: 1, tapasLink: "https://tapas.io/episode/3871101", preview: "C'est peut-être ça, le plus bizarre. Les fanions claquent au-dessus des quais, des lanternes colorées balancent avec le vent, on entend encore des rires, des verres qu'on cogne, des vendeurs qui hurlent des prix comme si le monde allait rester simple encore longtemps. Et nous, on embarque.\n\nJe garde une main sur la rambarde pendant que le navire s'arrache lentement du quai. Le bois gémit, les cordages grincent, les voiles prennent l'air avec un bruit sec. Sous mes bottes, le pont vibre juste assez pour me..." },
    { id: 77, title: "L'alliage et l'Abysse", filename: "ch77_L’alliage et l’abysse.md", season: 1, tapasLink: "https://tapas.io/episode/3871104", preview: "La forge de Varkas Morvane ne ressemble pas aux ateliers que je connais.\n\nIci, rien ne déborde vraiment. Rien ne traîne. Même la chaleur paraît rangée. Elle monte droit, tenue par des conduits métalliques noirs qui traversent le plafond comme des artères disciplinées. Les établis sont alignés au cordeau, les outils suspendus dans un ordre presque insultant, et les clients restent naturellement à distance, comme si l'endroit imposait tout seul sa propre hiérarchie." },
    { id: 78, title: "L'Épine de Murmurocéan", filename: "ch78_L'Épine de Murmurocéan.md", season: 1, tapasLink: "https://tapas.io/episode/3871106", preview: "L'eau avale tout.\n\nElle ne tombe pas, elle ne coule pas - elle disparaît. C'est la seule manière que j'ai trouvée pour décrire ce que je vois depuis le moment où j'ai franchi la surface. Le Grand Noir de l'Abysse n'est pas simplement obscur : il est absorbant. Comme si la lumière ne cherchait même plus à y entrer, comme si elle avait compris depuis longtemps que c'était inutile." },
    { id: 79, title: "L'Impératrice Oubliée", filename: "ch79_L'Impératrice Oubliée.md", season: 1, tapasLink: "https://tapas.io/episode/3871108", preview: "Le pont du navire est derrière nous depuis un moment déjà, et franchement, la seule chose à laquelle je pense en ce moment, c'est que mon épaule me fait toujours autant souffrir.\n\nJe la tourne lentement dans son articulation, histoire de tester, et la douleur me répond avec une précision satisfaisante. Pas de dégâts profonds, juste ce genre de tension qui s'est logée là et refuse de partir. Un souvenir de la traction. L'épine qui résistait, l'eau noire qui poussait dans le mauvais sens, et ma dague qui avait..." },
    { id: 80, title: "Le Don de Manelis", filename: "ch80_Le Don de Manelis.md", season: 1, tapasLink: "https://tapas.io/episode/3871114", preview: "Orizon est une ville qui ne crie pas.\n\nC'est ça, le problème. Tout le monde murmure, tout le monde glisse entre les rues comme de l'eau entre les pierres, et le silence qui en résulte n'est pas un silence de paix - c'est un silence de retenue. Comme si la cité entière retenait son souffle depuis des siècles et avait fini par oublier comment expirer." },
    { id: 81, title: "Le Seuil des Neiges", filename: "ch81_Le Seuil des Neiges.md", season: 1, tapasLink: "https://tapas.io/episode/3871117", preview: "La plaine s'ouvre devant nous comme une page qu'on aurait enfin le droit de tourner. Le silence d'Orizon colle encore à ma cape, quelque part entre les plis du tissu et l'arrière de mon crâne, et je sens mon épaule droite tirer à chaque fois que le vent s'engouffre sous mon manteau. Pas une vraie douleur. Juste cette raideur tenace qui s'installe dès que le froid d'Aetheris commence à mordre pour de vrai, une sorte de rappel que mon corps a veillé trop longtemps et que personne, pas même moi, ne lui a demandé..." },
    { id: 82, title: "La Chute du Rempart", filename: "ch82_La Chute du Rempart.md", season: 1, tapasLink: "https://tapas.io/episode/3871121", preview: "Le vent d'Aetheris n'a plus la même voix ici.\n\nIl ne siffle pas comme au-dessus des plaines, il ne gronde pas comme dans les gorges. Ici, dans ce recoin du Désert Blanc où le sol crisse sous chaque pas, il murmure à ras de neige, presque timide, comme s'il avait lui aussi repéré quelque chose qu'il préférait ne pas déranger. La poudreuse monte par petites volutes à chaque foulée, se dépose sur mes bottes, sur les bords de ma cape, et ne fond pas. Rien ne fond, dans ce froid-là. Il est trop sec, trop pur, trop..." },
    { id: 83, title: "Aberration", filename: "ch83_Aberration.md", season: 1, tapasLink: "https://tapas.io/episode/3871125", preview: "Qu'est-ce que je fous debout ?\n\nC'est la dernière phrase qui passe. Pas une pensée entière, pas une vraie question, juste un petit tas de mots qui se cogne contre l'intérieur de mon crâne pendant que la glace vient vers ma joue. Mon corps tombe, franchement il tombe, la lance du Haut Orc a ouvert mon buste de l'épaule jusqu'à la hanche et la douleur a cessé d'être une douleur pour devenir un bruit, un grondement sourd sous mes côtes. Et pourtant, quelque chose en moi est debout." },
    { id: 84, title: "Heritage de la Lance", filename: "ch84_Heritage de la Lance.md", season: 1, tapasLink: "https://tapas.io/episode/3871129", preview: "Je garde les yeux ouverts depuis un moment.\n\nPas vraiment réveillée. Pas vraiment endormie non plus. Juste coincée quelque part entre les deux, dans ce genre de silence où le monde semble respirer à ma place parce que moi, franchement, je n'en ai pas la force." },
    { id: 85, title: "Retour à Tharis", filename: "ch85_Retour à Tharis.md", season: 1, tapasLink: "https://tapas.io/episode/3890182", preview: "La route avale les jours avec une patience presque cruelle.\n\nAu début, je ne sens pas vraiment la différence entre avancer et rester couchée. Mon monde tient dans le balancement d'une couverture, dans la chaleur d'un manteau posé sur mes épaules, dans le grincement d'une roue ou le craquement d'une branche sous les bottes de Hendor. Les terres froides de Neusern restent derrière nous par morceaux, comme si le paysage refusait de se détacher d'un seul coup. La neige persiste dans les creux. Le vent d'Aetheris..." },
    { id: 86, title: "Le retour du Quattro", filename: "ch86_Le retour du Quattro.md", season: 1, tapasLink: "https://tapas.io/episode/3890185", preview: "Le miroir de ma chambre ne me rend pas vraiment mon visage.\n\nIl me rend une version déplacée de moi-même. Un peu trop pâle. Un peu trop droite. Un peu trop calme pour quelqu'un qui a encore des bandages du cou jusqu'au bas du buste et une cicatrice, nette, presque insolente, qui coupe ma joue comme si elle avait toujours prévu de s'installer là." },
    { id: 87, title: "L'Éclosion des Uniques", filename: "ch87_L’Éclosion des Uniques.md", season: 1, tapasLink: "https://tapas.io/episode/3890189", preview: "Le vent nous pousse presque dans le dos jusqu'à la trappe du Perchoir.\n\nEnfin, pousser, c'est gentil. Il nous agresse. Il siffle entre les pierres de la tour, s'engouffre sous les manteaux, mord les doigts même à travers les gants, et plaque contre mes joues une neige fine qui ne tombe même pas vraiment. Elle flotte de travers, sèche, nerveuse, comme si Aetheris avait décidé de nous râper le visage avant de nous laisser rentrer." },
    { id: 88, title: "Uniques Descente", filename: "ch88_Uniques Descente.md", season: 1, tapasLink: "https://tapas.io/episode/3890192", preview: "Le froid me mord encore les joues quand on quitte enfin le bord du ciel.\n\nLe Perchoir reste derrière nous, immense et silencieux, planté au-dessus de la vallée comme s'il n'avait jamais tremblé, jamais respiré, jamais accueilli la Forge. La neige fraîche étouffe nos pas sur les premières marches extérieures, et le vent d'Aetheris glisse entre les pierres avec ce bruit long, râpeux, un peu trop vivant. Ce n'est plus le blizzard furieux de la montée. Là, au moins, on distingue la pente, les sapins, les plaques de..." },
    { id: 89, title: "Le Mandat d'Oakhaven", filename: "ch89_Le Mandat d’Oakhaven.md", season: 1, tapasLink: "https://tapas.io/episode/3890197", preview: "Quatre jours, c'est long.\n\nEnfin... non. Mais, quatre jours, ce n'est rien. C'est à peine le temps qu'il faut pour que la poussière retombe après un gros événement, pour que les adultes arrêtent de poser des questions avec des yeux trop attentifs, pour que Finn cesse de raconter quinze fois la même explosion en changeant juste l'angle de ses bras à chaque version." },
    { id: 90, title: "La Garnison d'Oakhaven", filename: "ch90_La Garnison d’Oakhaven.md", season: 1, tapasLink: "https://tapas.io/episode/3890200", preview: "Le froid d'Oakhaven a quelque chose de propre.\n\nPas propre dans le sens agréable, non. Plutôt dans le sens où il ne laisse rien traîner. Il coupe les odeurs, sèche la gorge, serre les joues et transforme chaque respiration en petite preuve de survie. La neige ne tombe pas en grosses plaques molles comme dans les images confortables qu'on garde de la Terre. Ici, en Aetheris, elle grince. Elle accroche aux bottes, elle durcit sur les rebords de fenêtres, elle s'entasse contre les cabanes en rondins comme si elle..." },
    { id: 91, title: "Le Poids du Silence", filename: "ch91_Le Poids du Silence.md", season: 1, tapasLink: "https://tapas.io/episode/3890203", preview: "Le lendemain, je ne laisse à personne le temps de s'installer dans le confort d'une routine.\n\nLa neige tombe encore sur Oakhaven, fine et serrée, presque silencieuse. Elle ne s'écrase pas vraiment sur les toits ; elle les ensevelit avec une patience de prédateur. Tout devient blanc, mou, froid, et même les sons paraissent hésiter avant de traverser l'air. Les sabots des chevaux de passage s'étouffent dans les ruelles. Les volets grincent plus bas. Les gardes parlent moins fort, comme si le village entier avait..." },
    { id: 92, title: "Le Faux Retour", filename: "ch92_Le Faux Retour.md", season: 1, tapasLink: "https://tapas.io/episode/3890208", preview: "Le sourire ne reste pas longtemps sur mon visage.\n\nPas parce que Finn me regarde comme si je venais enfin d'autoriser une explosion publique. Pas parce que Nova a cette expression très calme qui veut dire qu'il a déjà trouvé trois failles dans mon idée avant même que je la formule. Pas parce que Scylla, elle, regarde la porte de l'auberge comme si quelqu'un pouvait entrer avec une réponse accrochée au manteau." },
    { id: 93, title: "La Ligne du Nord-Est", filename: "ch93_La Ligne du Nord-Est.md", season: 1, tapasLink: "", preview: "La neige n'a pas effacé le silence.\n\nElle a recouvert les traces autour des portes d'Oakhaven, épaissi les toits, blanchi les pieux de la palissade et rendu les rues presque propres. Elle a avalé les empreintes du prisonnier quand on l'a ramené la veille, puis celles de nos bottes quand nous sommes repartis vers Tharis, puis encore celles de notre retour tardif, après le rapport à la Guilde." },
    { id: 94, title: "Assaut du Relais", filename: "ch94_Assaut du Relais.md", season: 1, tapasLink: "", preview: "La nuit ne tombe pas sur Oakhaven.\n\nElle se ferme." },
    { id: 95, title: "Sous le Rouge", filename: "ch95_Sous le Rouge.md", season: 1, tapasLink: "", preview: "Oakhaven ne dort pas.\n\nPas vraiment." },
    { id: 96, title: "Le Jour Partagé", filename: "ch96_Le Jour Partagé.md", season: 1, tapasLink: "", preview: "La première marche après la Guilde est trop basse.\n\nOu trop haute." },
    { id: 97, title: "À Dans Deux Ans", filename: "ch97_À Dans Deux Ans.md", season: 1, tapasLink: "", preview: "Le lendemain de l'anniversaire partagé, la maison Ashford sent encore le sucre, la braise, la laine humide et les décisions qui n'ont pas encore été dites à voix haute.\n\nC'est une odeur très précise." },
    { id: 98, title: "Le Premier Relais", filename: "ch98_Le Premier Relais.md", season: 1, tapasLink: "", preview: "Le matin du départ sent le cuir froid, la laine pliée trop vite, le pain emballé dans des torchons propres et la panique très polie.\n\nPas la vraie panique." },
    { id: 99, title: "Le Portail", filename: "ch99_Le Portail.md", season: 1, tapasLink: "", preview: "Le deuxième matin autonome commence avec une chaussette.\n\nPas une menace." },
    { id: 100, title: "Last Clause", filename: "ch100_Last Clause.md", season: 2, tapasLink: "", preview: "On franchit les portes.\n\nCe n'est pas spectaculaire." },
    { id: 101, title: "Copies blanches", filename: "ch101_Copies blanches.md", season: 2, tapasLink: "", preview: "La première cloche a un bruit beaucoup trop propre.\n\nPas fort." },
    { id: 102, title: "Admis", filename: "ch102_Admis.md", season: 2, tapasLink: "", preview: "Le papier officiel reste accroché au tableau bleu et argent comme s'il n'avait pas conscience de ce qu'il vient de faire à toute une galerie.\n\nAutour de nous, les candidats se mettent en mouvement par vagues nerveuses. Pas vraiment une foule. Plutôt une hésitation collective avec des chaussures, des manteaux et des respirations trop courtes. Certains partent tout de suite vers l'aile administrative. D'autres relisent la phrase comme si elle allait changer de sens au troisième passage. Deux candidats derrière..." },
    { id: 103, title: "Premier soir", filename: "ch103_Premier soir.md", season: 2, tapasLink: "", preview: "Le couloir du dortoir féminin n'a pas changé.\n\nÉvidemment." },
    { id: 104, title: "Pré-rentrée à plusieurs", filename: "ch104_Pre-rentree a plusieurs.md", season: 2, tapasLink: "", preview: "Je dors trop bien.\n\nC'est une erreur." },
    { id: 105, title: "Veille de Première-Quatre", filename: "ch105_Veille de Premiere-Quatre.md", season: 2, tapasLink: "", preview: "Le problème avec une école immense, c'est qu'elle peut encore se remplir alors qu'on a déjà l'impression qu'elle est pleine.\n\nLe 27 Serewin, Hochedenia bruisse déjà de pas, de voix, de plateaux de petit-déjeuner, de portes qui s'ouvrent au mauvais moment et de couloirs qui se ressemblent juste assez pour humilier les nouveaux. Le 28, elle gagne encore des candidats. Le 29, des silhouettes arrivent avec des malles, des familles, des responsables, des uniformes pliés contre la poitrine et cette expression..." },
    { id: 106, title: "Rentrée de Première-Quatre", filename: "ch106_Rentree de Premiere-Quatre.md", season: 2, tapasLink: "", preview: "Je dors mal.\n\nPas assez mal pour que ça devienne dramatique. Pas assez bien pour que mon corps accepte de me mentir avec conviction. Je passe une partie de la nuit à me retourner dans mon lit, à chercher une position où le fragment dans ma poitrine fait moins de bruit, où le souvenir de mon discours se replie tout seul, où la phrase adressée à Martin Delune cesse de revenir avec cette clarté indécente qui donne envie de s'enterrer sous une couverture et de prétendre qu'on a quitté le pays." },
    { id: 107, title: "Premier geste", filename: "ch107_Premier geste.md", season: 2, tapasLink: "", preview: "Le problème avec les consignes simples, c'est qu'elles donnent à Finn l'impression d'avoir réussi quelque chose d'important.\n\nNous quittons le réfectoire avec la classe qui se reforme par morceaux autour de nous, des plateaux abandonnés derrière, des sacs remis sur les épaules, des supports personnels vérifiés pour la troisième fois en moins d'une heure. La matinée a laissé dans les corps une fatigue étrange, pas celle d'un combat, pas celle d'une marche trop longue. Une fatigue de plan, de règlement, de..." },
    { id: 108, title: "Une seule intention", filename: "ch108_Une seule intention.md", season: 2, tapasLink: "", preview: "Il y a des phrases qui devraient avoir la politesse de rester dans les salles où on les a entendues.\n\nLa phrase d'Édith Veyrane, elle, n'a aucune éducation." },
    { id: 109, title: "Ce que Nulléon ne prend pas", filename: "ch109_Ce que Nulléon ne prend pas.md", season: 2, tapasLink: "", preview: "Il y a des actes illégaux qui devraient au moins avoir la décence de devenir plus simples avec l'habitude.\n\nCelui-ci ne fait aucun effort." },
    { id: 110, title: "Trois appels stables", filename: "ch110_Trois appels stables.md", season: 2, tapasLink: "", preview: "Il y a des images qui devraient avoir la gentillesse d'attendre le réveil complet avant de revenir.\n\nLa rune, elle, n'a aucune patience." },
    { id: 111, title: "Le débit de l’ombre", filename: "ch111_Le débit de l’ombre.md", season: 2, tapasLink: "", preview: "Il y a des après-midis qui commencent avec la sensation très nette que le monde a décidé de reprendre son rythme sans demander si vous avez fini de comprendre la matinée.\n\nLe cours d'Édith vient à peine de se vider dans les couloirs que les groupes se découpent déjà selon des directions que je ne connais pas encore. Première-Quatre n'est plus vraiment une classe pendant quelques heures. C'est un tas de gens que les horaires attrapent par le col pour les envoyer chacun vers une partie différente d'Hochedenia." },
    { id: 112, title: "Cupidon dans les gradins", filename: "ch112_Cupidon dans les gradins.md", season: 2, tapasLink: "", preview: "Il existe une différence importante entre se préparer à combattre et se préparer à regarder d'autres personnes combattre.\n\nJ'essaie de m'en convaincre depuis cinq minutes." },
    { id: 113, title: "À un souffle", filename: "ch113_À un souffle.md", season: 2, tapasLink: "", preview: "Il existe aussi une différence importante entre regarder des gens combattre et continuer à penser pendant qu'ils le font.\n\nLa seconde activité est beaucoup plus dangereuse." },
    { id: 114, title: "Que ce soit nous", filename: "ch114_Que ce soit nous.md", season: 2, tapasLink: "", preview: "Il existe probablement des manières dignes d'organiser un rendez-vous entre deux personnes qui s'aiment.\n\nJe n'en ai trouvé aucune." },
    { id: 115, title: "À trois jours près", filename: "ch115_À trois jours près.md", season: 2, tapasLink: "", preview: "Le premier matin libre de notre semaine commence sans cloche, sans uniforme et sans personne pour m'expliquer ce que mon mana fait de travers.\n\nJe reste allongée quelques secondes, juste pour vérifier que c'est vrai." },
    { id: 116, title: "Aplomb", filename: "ch116_Aplomb.md", season: 2, tapasLink: "", preview: "Le 8 Soléor commence avec une cloche, un uniforme et cette sensation très particulière que le week-end n'a pas réellement disparu, mais qu'il a été rangé dans un coin par quelqu'un de plus organisé que nous.\n\nCe quelqu'un n'est pas moi." },
    { id: 117, title: "Voix de classe", filename: "ch117_Voix de classe.md", season: 2, tapasLink: "", preview: "Le lendemain d'une défaite propre a une texture très particulière.\n\nCe n'est pas une douleur dramatique. Ce n'est pas le genre de douleur qui oblige quelqu'un à rester couchée en contemplant le plafond avec la dignité fragile d'une héroïne blessée. C'est plus sournois. Ça se glisse dans l'épaule quand je tends le bras vers ma chemise, dans le genou quand je pose le pied par terre, dans le flanc quand je respire un peu trop fort parce que j'ai eu l'audace de dormir." },
];

// --- Publication / visibilité ---------------------------------------------
// Un chapitre est "publié" (donc visible sur le site) uniquement s'il a un lien
// Tapas. Ce champ est renseigné automatiquement par tools/sync-tapas.mjs à
// partir de ce qui est réellement en ligne sur Tapas. Les chapitres écrits mais
// pas encore sortis sur Tapas ont tapasLink === "" et restent masqués.
function isPublished(ch) {
  return !!ch && typeof ch.tapasLink === 'string' && ch.tapasLink.trim() !== '';
}
// Sous-ensemble ordonné des chapitres visibles sur le site public.
const publishedChapters = chapters.filter(isPublished);
